//! Live admitted cloud evidence, independent of persistent terrain publication.
use super::lio::{self, LioCloudEnvelope};
use crate::{CodecError, CodecResult};

pub const SCHEMA_VERSION: i32 = 1;
/// Generated by lcm-gen 1.5.2 from lcmtypes/nuwax_msgs/RecentCloud3D.lcm.
pub const FINGERPRINT: [u8; 8] = 0xfefc4448c3229419_u64.to_be_bytes();
pub const TYPE_NAME: &str = "nuwax_msgs.RecentCloud3D";
pub const DEFAULT_TOPIC: &str = "/nav/observations3d";
pub const MAX_BYTES: usize = 2 * 1024 * 1024;

#[derive(Clone, Debug, PartialEq)]
