pub fn encode_body(value: &RecentCloud3D) -> CodecResult<Vec<u8>> {
    encode_borrowed(
        value.producer_runtime_generation,
        &value.session_id,
        value.session_generation,
        value.map_frame_generation,
        value.commit_boot_nonce,
        value.cloud.as_ref(),
        &value.ground_point_indices,
    )
}
/// Borrow the admitted cloud allocation; the publisher need not clone all points
/// into a second owned DTO before serialization.
pub fn encode_borrowed(
    producer: i64,
    session: &str,
    generation: i64,
    frame: i64,
    boot: [u8; 16],
    cloud: Option<&LioCloudEnvelope>,
    members: &[u32],
) -> CodecResult<Vec<u8>> {
    validate_domain(producer, session, generation, frame)?;
    if boot == [0; 16] {
        return Err(bad("recent cloud requires canonical owner boot identity"));
    }
    validate_members(cloud, members)?;
    let payload_capacity = cloud.map_or(0, |cloud| cloud.cloud.data.len() + 512);
    let mut out = Vec::with_capacity(64 + session.len() + members.len() * 4 + payload_capacity);
    out.extend(SCHEMA_VERSION.to_be_bytes());
    out.extend(producer.to_be_bytes());
    out.extend(((session.len() + 1) as i32).to_be_bytes());
    out.extend(session.as_bytes());
    out.push(0);
    out.extend(generation.to_be_bytes());
    out.extend(frame.to_be_bytes());
    out.extend(boot);
    out.push(u8::from(cloud.is_none()));
    out.extend((members.len() as i32).to_be_bytes());
    for member in members {
        out.extend((*member as i32).to_be_bytes());
    }
    let length_offset = out.len();
    out.extend(0_i32.to_be_bytes());
    let payload_offset = out.len();
    if let Some(cloud) = cloud { lio::encode_lio_cloud_envelope_into(cloud, &mut out)?; }
    let payload_length = i32::try_from(out.len() - payload_offset).map_err(|_| bad("recent cloud payload length overflow"))?;
    out[length_offset..payload_offset].copy_from_slice(&payload_length.to_be_bytes());
    if out.len() > MAX_BYTES {
        return Err(bad("recent cloud exceeds wire budget"));
    }
    Ok(out)
}
pub fn decode_body(input: &[u8]) -> CodecResult<RecentCloud3D> {
    if input.len() > MAX_BYTES {
        return Err(bad("recent cloud exceeds wire budget"));
    }
    let mut reader = Reader { input, pos: 0 };
    if reader.i32()? != SCHEMA_VERSION {
        return Err(bad("unsupported recent cloud version"));
    }
    let producer_runtime_generation = reader.i64()?;
    let len = reader.i32()?;
    if !(2..=1025).contains(&len) {
        return Err(bad("recent cloud session length invalid"));
    }
    let session = reader.take(len as usize)?;
    if session.last() != Some(&0) {
        return Err(bad("recent cloud session lacks terminator"));
    }
    let session_id = std::str::from_utf8(&session[..session.len() - 1])
        .map_err(|_| bad("invalid session UTF-8"))?
        .to_owned();
    let session_generation = reader.i64()?;
    let map_frame_generation = reader.i64()?;
    let commit_boot_nonce = reader.take(16)?.try_into().unwrap();
    if commit_boot_nonce == [0; 16] {
        return Err(bad("recent cloud requires canonical owner boot identity"));
    }
    let cleared = match reader.take(1)?[0] {
        0 => false,
        1 => true,
        _ => return Err(bad("invalid recent cloud revoke flag")),
    };
    let count = reader.i32()?;
    if count < 0 || i64::from(count) > lio::MAX_LIO_EMITTED_POINT_COUNT {
        return Err(bad("recent cloud ground count exceeds budget"));
    }
    let mut ground_point_indices = Vec::with_capacity(count as usize);
    for _ in 0..count {
        ground_point_indices
            .push(u32::try_from(reader.i32()?).map_err(|_| bad("negative ground point index"))?);
    }
    let bytes = reader.i32()?;
    if bytes < 0 || bytes as usize > MAX_BYTES {
        return Err(bad("recent cloud payload length invalid"));
    }
    let encoded = reader.take(bytes as usize)?;
    if reader.pos != input.len() {
        return Err(bad("recent cloud has trailing bytes"));
    }
    let cloud = if cleared {
        if bytes != 0 || !ground_point_indices.is_empty() {
            return Err(bad("revoked cloud must have no payload or ground claims"));
        }
        None
    } else {
        Some(lio::decode_lio_cloud_envelope(encoded)?)
    };
    validate_domain(
        producer_runtime_generation,
        &session_id,
        session_generation,
        map_frame_generation,
    )?;
    validate_members(cloud.as_ref(), &ground_point_indices)?;
    Ok(RecentCloud3D {
        producer_runtime_generation,
        session_id,
        session_generation,
        map_frame_generation,
        commit_boot_nonce,
        cloud,
        ground_point_indices,
    })
}
struct Reader<'a> {
    input: &'a [u8],
    pos: usize,
}
impl<'a> Reader<'a> {
    fn take(&mut self, count: usize) -> CodecResult<&'a [u8]> {
        let end = self
            .pos
            .checked_add(count)
            .filter(|end| *end <= self.input.len())
            .ok_or_else(|| bad("truncated recent cloud"))?;
        let value = &self.input[self.pos..end];
        self.pos = end;
        Ok(value)
    }
    fn i32(&mut self) -> CodecResult<i32> {
        Ok(i32::from_be_bytes(self.take(4)?.try_into().unwrap()))
    }
    fn i64(&mut self) -> CodecResult<i64> {
        Ok(i64::from_be_bytes(self.take(8)?.try_into().unwrap()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn explicit_revocation_roundtrips_and_rejects_fake_data() {
        let value = RecentCloud3D {
            producer_runtime_generation: 1,
            session_id: "map-owner".into(),
            session_generation: 2,
            map_frame_generation: 3,
            commit_boot_nonce: [1; 16],
            cloud: None,
            ground_point_indices: vec![],
        };
        let bytes = encode_body(&value).unwrap();
        assert_eq!(decode_body(&bytes).unwrap(), value);
        for n in 0..bytes.len() {
            assert!(decode_body(&bytes[..n]).is_err());
        }
        let mut trailing = bytes.clone();
        trailing.push(0);
        assert!(decode_body(&trailing).is_err());
        let mut bad = value.clone();
        bad.ground_point_indices = vec![0];
        assert!(encode_body(&bad).is_err());
        let mut bad = value;
        bad.session_generation = 0;
        assert!(encode_body(&bad).is_err());
    }
    fn live() -> RecentCloud3D {
        use super::super::schema::{Header, PointCloud2, PointField};
        let cloud = PointCloud2 {
            header: Header {
                seq: 7,
                stamp_sec: 1,
                stamp_nsec: 0,
                frame_id: "map".into(),
            },
            height: 1,
            width: 2,
            fields: ["x", "y", "z"]
                .iter()
                .enumerate()
                .map(|(i, name)| PointField {
                    name: (*name).into(),
                    offset: (i * 4) as i32,
                    datatype: 7,
                    count: 1,
                })
                .collect(),
            point_step: 12,
            row_step: 24,
            data: [0.01_f32, 0.02, 0.03, 0.01, 0.02, 0.4]
                .into_iter()
                .flat_map(f32::to_le_bytes)
                .collect(),
            is_dense: true,
            ..Default::default()
        };
        RecentCloud3D {
            producer_runtime_generation: 5,
            session_id: "ground-owner".into(),
            session_generation: 3,
            map_frame_generation: 4,
            commit_boot_nonce: [9; 16],
            ground_point_indices: vec![0],
            cloud: Some(LioCloudEnvelope {
                schema_version: 1,
                backend: lio::LIO_BACKEND_DEVICE,
                runtime_generation: 2,
                source_sequence: 7,
                source_timestamp_ns: 1_000_000_000,
                correlated_odometry_source_sequence: 7,
                correlated_odometry_source_timestamp_ns: 1_000_000_000,
                sensor_frame_id: "sensor".into(),
                body_frame_id: "body".into(),
                odom_frame_id: "odom".into(),
                map_frame_id: "map".into(),
                registration_state: lio::LIO_REGISTRATION_REGISTERED_MAP,
                source_point_count: 2,
                emitted_point_count: 2,
                cloud,
            }),
        }
    }
    #[test]
    fn admitted_points_and_ground_indices_roundtrip_without_changing_source_time() {
        let value = live();
        let bytes = encode_body(&value).unwrap();
        assert_eq!(decode_body(&bytes).unwrap(), value);
        for length in 0..bytes.len() {
            assert!(decode_body(&bytes[..length]).is_err());
        }
        let mut trailing = bytes.clone();
        trailing.push(0);
        assert!(decode_body(&trailing).is_err());
        for indices in [vec![0, 0], vec![1, 0], vec![2], vec![u32::MAX]] {
            let mut invalid = value.clone();
            invalid.ground_point_indices = indices;
            assert!(encode_body(&invalid).is_err());
        }
        let mut invalid = value;
        invalid.cloud.as_mut().unwrap().registration_state = lio::LIO_REGISTRATION_RAW_SENSOR;
        assert!(encode_body(&invalid).is_err());
    }
    #[test]
    #[ignore = "release codec allocation/copy timing diagnostic"]
    fn recent_nested_cloud_decode_cost() {
        let mut value = live();
        let cloud = value.cloud.as_mut().unwrap();
        cloud.source_point_count = 100_000;
        cloud.emitted_point_count = 100_000;
        cloud.cloud.width = 100_000;
        cloud.cloud.row_step = cloud.cloud.width * cloud.cloud.point_step;
        cloud.cloud.data = vec![0; cloud.cloud.row_step as usize];
        let data_bytes = cloud.cloud.data.len();
        let wire = encode_body(&value).unwrap();
        assert_eq!(decode_body(&wire).unwrap(), value);
        let iterations = 2_000;
        let start = std::time::Instant::now();
        for _ in 0..iterations {
            std::hint::black_box(decode_body(std::hint::black_box(&wire)).unwrap());
        }
        eprintln!("recent_nested_cloud iterations={iterations} data_bytes={data_bytes} elapsed_ms={:.3}",
            start.elapsed().as_secs_f64() * 1000.0);
    }

    #[test]
    fn generated_python_decodes_and_reencodes_the_exact_live_packet() {
        use std::io::Write;
        use std::process::{Command, Stdio};
        let value = live();
        let mut full = FINGERPRINT.to_vec();
        full.extend(encode_body(&value).unwrap());
        let mut child = Command::new("python3")
            .arg("-c")
            .arg(
                r#"
import sys
from nuwax_msgs.RecentCloud3D import RecentCloud3D
from nuwax_msgs.LioCloudEnvelope import LioCloudEnvelope
raw=sys.stdin.buffer.read()
value=RecentCloud3D.decode(raw)
assert value.producer_runtime_generation==5 and value.session_id=='ground-owner'
assert list(value.ground_point_indices)==[0]
cloud=LioCloudEnvelope.decode(bytes(value.cloud_bytes))
assert cloud.source_sequence==7 and cloud.source_timestamp_ns==1000000000
assert cloud.cloud.width==2
assert value.encode()==raw
"#,
            )
            .env(
                "PYTHONPATH",
                std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                    .join("../../lcmtypes/generated/python"),
            )
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("Python codec verifier");
        child.stdin.take().unwrap().write_all(&full).unwrap();
        let result = child.wait_with_output().unwrap();
        assert!(
            result.status.success(),
            "{}",
            String::from_utf8_lossy(&result.stderr)
        );
    }
}
